#include <bits/stdc++.h>
#define endl '\n'

using namespace std;

using ll = long long;

const ll N = 2e5 + 5;

int n, x[N], pos[N];
struct node
{
	int x, y, id;
} a[N];
struct tnode
{
	int l, r, val, pos;
	const friend tnode operator+(const tnode &x, const tnode &y) { return {x.l, y.r, max(x.val, y.val), x.val >= y.val ? x.pos : y.pos}; }
} t[N << 2];
set<int> st;

void maintain(int p) { t[p] = t[p << 1] + t[p << 1 | 1]; }

void build(int p = 1, int l = 1, int r = n)
{
	t[p] = {l, r};
	if (l == r)
	{
		t[p].val = a[pos[l]].y;
		return;
	}
	int mid = (l + r) >> 1;
	build(p << 1, l, mid);
	build(p << 1 | 1, mid + 1, r);
	maintain(p);
}

tnode query(int l, int r, int p = 1)
{
	if (l <= t[p].l && t[p].r <= r)
		return t[p];
	int mid = (l + r) >> 1;
	if (r <= mid)
		return query(l, r, p << 1);
	if (l > mid)
		return query(l, r, p << 1 | 1);
	return query(l, r, p << 1) + query(l, r, p << 1 | 1);
}

void init() {}

void solve()
{
	cin >> n;
	for (int i = 1; i <= n; ++i)
		cin >> a[i].x >> a[i].y, a[i].id = i, st.insert(i);
	sort(a + 1, a + n + 1, [](node x, node y)
		 { return x.y == y.y ? x.x < y.x : x.y < y.y; });
	for (int i = 1; i <= n; ++i)
	{
		auto it = st.lower_bound(a[i].x);
		x[a[i].id] = *it;
		pos[*it] = i;
		st.erase(it);
	}
	build();
	for (int i = 1; i <= n; ++i)
	{
		if (a[pos[i]].x == i)
			continue;
		tnode it = query(a[pos[i]].x, i - 1);
		if (it.val >= i)
		{
			cout << "NO" << endl;
			for (int i = 1; i <= n; ++i)
				cout << x[i] << " \n"[i == n];
			swap(x[a[pos[i]].id], x[a[pos[it.pos]].id]);
			for (int i = 1; i <= n; ++i)
				cout << x[i] << " \n"[i == n];
			return;
		}
	}
	cout << "YES" << endl;
	for (int i = 1; i <= n; ++i)
		cout << x[i] << " \n"[i == n];
}

int main()
{
	ios::sync_with_stdio(false);
	cin.tie(nullptr);
	cout.tie(nullptr);
	int _ = 1;
	// cin >> _;
	init();
	while (_--)
		solve();
	return 0;
}

